import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

const LABEL_COLUMN_WIDTH = 120;
const VALUE_COLUMN_WIDTH = 76;
const COLUMN_GAP = 12;

/**
 * Creates all totals styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createTotalsStyles = (t: PdfcnTheme) => {
  const { fontWeights, spacing, typography } = t.primitives;
  const text = {
    fontFamily: t.typography.body.fontFamily,
    fontSize: typography.xs,
    lineHeight: t.typography.body.lineHeight,
  };

  return StyleSheet.create({
    // Right alignment uses main-axis justification: Forme ignores alignSelf.
    alignRight: {
      justifyContent: "flex-end",
    },
    block: {
      display: "flex",
      flexDirection: "column",
    },
    blockFull: {
      flex: 1,
    },
    blockRight: {
      maxWidth: "100%",
      width: LABEL_COLUMN_WIDTH + COLUMN_GAP + VALUE_COLUMN_WIDTH,
    },
    container: {
      display: "flex",
      flexDirection: "row",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    label: {
      ...text,
      color: t.colors.mutedForeground,
    },
    labelRight: {
      textAlign: "right",
    },
    // Fixed label column so breakdown labels hug the value column
    labelWrap: {
      flexShrink: 1,
      minWidth: 0,
      paddingRight: COLUMN_GAP,
      width: LABEL_COLUMN_WIDTH + COLUMN_GAP,
    },
    // flex lives on the wrapping View, not the Text: see list.styles.ts
    labelWrapFull: {
      flexGrow: 1,
      flexShrink: 1,
      minWidth: 0,
      paddingRight: spacing[4],
    },
    row: {
      alignItems: "flex-start",
      flexDirection: "row",
      paddingVertical: spacing[1],
    },
    totalRow: {
      borderTopStyle: "solid",
      borderTopWidth: 1,
      marginTop: spacing[1],
      paddingTop: spacing[2],
    },
    totalText: {
      fontSize: typography.base,
      fontWeight: fontWeights.bold,
    },
    value: {
      ...text,
      color: t.colors.foreground,
      flexShrink: 0,
      textAlign: "right",
      width: VALUE_COLUMN_WIDTH,
    },
    valueFull: {
      ...text,
      color: t.colors.foreground,
      flexShrink: 0,
      textAlign: "right",
    },
  });
};

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  Text as PDFText,
  View,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createTotalsStyles } from "./totals.styles";
import type { TotalsProps } from "./totals.types";

export type { TotalsAlign, TotalsItem, TotalsProps } from "./totals.types";

export const Totals = ({
  items,
  totalLabel,
  total,
  align = "right",
  accentColor,
  style,
}: TotalsProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createTotalsStyles(theme), [theme]);
  const emphasis = resolveColor(accentColor ?? "primary", theme.colors);

  const isFull = align === "full";
  const containerStyles: Style[] = isFull
    ? [styles.container]
    : [styles.container, styles.alignRight];
  if (style) {
    containerStyles.push(...[style].flat());
  }
  const blockStyles: Style[] = [
    styles.block,
    isFull ? styles.blockFull : styles.blockRight,
  ];
  const labelWrapStyle = isFull ? styles.labelWrapFull : styles.labelWrap;
  const labelStyles: Style[] = isFull
    ? [styles.label]
    : [styles.label, styles.labelRight];
  const valueStyle = isFull ? styles.valueFull : styles.value;
  const totalRowStyles: Style[] = [
    styles.row,
    styles.totalRow,
    { borderTopColor: emphasis },
  ];
  const totalTextStyle: Style = { ...styles.totalText, color: emphasis };

  return (
    <View wrap={false} style={containerStyles}>
      <View style={blockStyles}>
        {items.map((item) => (
          <View key={item.label} style={styles.row}>
            <View style={labelWrapStyle}>
              <PDFText style={labelStyles}>{item.label}</PDFText>
            </View>
            <PDFText style={valueStyle}>{item.value}</PDFText>
          </View>
        ))}
        <View style={totalRowStyles}>
          <View style={labelWrapStyle}>
            <PDFText style={[...labelStyles, totalTextStyle]}>
              {totalLabel}
            </PDFText>
          </View>
          <PDFText style={[valueStyle, totalTextStyle]}>{total}</PDFText>
        </View>
      </View>
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

/** Horizontal layout of the totals block. */
export type TotalsAlign = "right" | "full";

/**
 * A single breakdown line shown above the grand total.
 * Props - `label` | `value`
 * @see {@link TotalsItem}
 */
export interface TotalsItem {
  label: string;
  value: string;
}

/**
 * Breakdown lines with an emphasized grand-total row, for invoices, quotes, and receipts.
 * Props - `items` | `totalLabel` | `total` | `align` | `accentColor` | `renderingBase` | `style`
 * @see {@link TotalsProps}
 */
export interface TotalsProps {
  items: TotalsItem[];
  totalLabel: string;
  total: string;
  /**
   * @default 'right'
   */
  align?: TotalsAlign;
  accentColor?: string;
  renderingBase?: "takumi" | "forme";
  style?: Style;
}
